create function pg_temp.uid(old_email text) returns uuid language sql stable as $$
  select u.id from auth.users u join tc_login_map m on u.email = m.new_email where m.old_email = $1;
$$;

do $$
begin
  if pg_temp.uid('getfit@urbanmuaythai.com') is null then
    raise exception 'NMS login ram@staff.urbanmuaythai.com not found';
  end if;
end $$;

insert into public.tc_tasks (id, workspace_id, client_key, name, note, category, link, start_date, start_time,
  duration_minutes, priority, recurrence, recurrence_days, non_negotiable, is_system, created_by, assigned_to,
  archived_at, created_at, updated_at)
select (t->>'id')::uuid, '2ac84d5d-65c8-494b-8c0f-d5e25b52ff22', t->>'client_key', t->>'name', t->>'note', t->>'category',
  t->>'link', (t->>'start_date')::date, (t->>'start_time')::time, (t->>'duration_minutes')::int, t->>'priority',
  t->>'recurrence', array(select jsonb_array_elements_text(t->'recurrence_days')), (t->>'non_negotiable')::boolean,
  (t->>'is_system')::boolean, pg_temp.uid(t->>'created_by'), pg_temp.uid(t->>'assigned_to'),
  (t->>'archived_at')::timestamptz, (t->>'created_at')::timestamptz, (t->>'updated_at')::timestamptz
from tc_src, jsonb_array_elements(d->'tasks') t
on conflict do nothing;

insert into public.tc_task_occurrences (id, task_id, occurrence_date, status, planned_time, duration_minutes, priority,
  note, gates, completed_by, updated_by, created_at, updated_at)
select (o->>'id')::uuid, (o->>'task_id')::uuid, (o->>'occurrence_date')::date, o->>'status', (o->>'planned_time')::time,
  (o->>'duration_minutes')::int, o->>'priority', o->>'note',
  array(select jsonb_array_elements_text(o->'gates')::boolean), pg_temp.uid(o->>'completed_by'),
  pg_temp.uid(o->>'updated_by'), (o->>'created_at')::timestamptz, (o->>'updated_at')::timestamptz
from tc_src, jsonb_array_elements(d->'occ') o
on conflict do nothing;

insert into public.tc_user_settings (workspace_id, user_id, workday_start, workday_end, break_minutes, updated_at)
select '2ac84d5d-65c8-494b-8c0f-d5e25b52ff22', pg_temp.uid(s->>'user_id'), (s->>'workday_start')::time,
  (s->>'workday_end')::time, (s->>'break_minutes')::int, (s->>'updated_at')::timestamptz
from tc_src, jsonb_array_elements(d->'settings') s
on conflict do nothing;

select (select count(*) from public.tc_tasks) tasks, (select count(*) from public.tc_task_occurrences) occurrences,
  (select count(*) from public.tc_user_settings) settings, (select count(*) from public.tc_members) members;
commit;
